<template>
<section class="world-time" :class="{'world-dark':dark}" aria-labelledby="world-time-title"><header><div><h2 id="world-time-title">世界时间</h2><p>十个城市与时区 · 按当地规则自动处理夏令时</p></div><button type="button" @click="expanded=!expanded" :aria-expanded="expanded">{{expanded?'收起':'展开'}}</button></header><template v-if="expanded"><div class="world-options"><label><input v-model="hour12" type="checkbox" />12 小时制</label><span>日期与 UTC 偏移均为城市当地时间</span></div><div class="world-grid"><article v-for="city in clocks" :key="city.zone"><div class="world-city"><strong class="world-city-name"><img v-if="city.flag" class="world-flag" :src="`${assetBase}country-flags/${city.flag}.svg`" :alt="`${city.country}国旗`" width="24" height="18" /><svg v-else class="world-globe" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6.5h14M5 17.5h14"/></svg>{{city.name}}</strong><span :class="{'world-day':city.daytime}">{{city.daytime?'日间':'夜间'}}</span></div><time :datetime="now.toISOString()" :aria-label="`${city.name} ${city.date} ${city.time} ${city.offset}`">{{city.time}}</time><div class="world-date">{{city.date}}<span>{{city.offset}}</span></div></article></div><p class="world-note">使用设备时钟与浏览器时区数据库；日间标记按当地 07:00–19:00 显示，不代表日出日落。</p></template></section>
</template>
<script>
import {worldCities,worldClock} from '../utils/world-time.mjs';
export default{name:'WorldTime',props:{dark:Boolean},data:()=>({assetBase:process.env.BASE_URL,expanded:true,now:new Date(),hour12:false,timer:null}),computed:{clocks(){return worldCities.map(city=>({...city,...worldClock(this.now,city.zone,this.hour12)}));}},mounted(){this.timer=setInterval(()=>{this.now=new Date();},1000);},beforeUnmount(){clearInterval(this.timer);}};
</script>
<style scoped>
.world-time{--w-text:#26364c;--w-muted:#7b8799;--w-line:rgba(105,128,160,.15);margin:18px 0 24px;padding:20px 24px;border:1px solid var(--w-line);border-radius:18px;background:rgba(255,255,255,.86);color:var(--w-text)}.world-dark{--w-text:#e2e9f4;--w-muted:#95a3b9;--w-line:rgba(145,164,194,.17);background:rgba(24,31,45,.92)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}h2{margin:0;font-size:16px}header p{margin:7px 0 0;font-size:12px;color:var(--w-muted)}button{border:1px solid var(--w-line);border-radius:7px;background:transparent;color:var(--w-text);font:inherit;font-size:12px;padding:6px 10px;cursor:pointer}button:focus-visible{outline:2px solid #43898d;outline-offset:2px}.world-options{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:18px 0 12px;font-size:11px;color:var(--w-muted)}.world-options label{display:flex;align-items:center;gap:5px}.world-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}.world-grid article{padding:13px;border:1px solid var(--w-line);border-radius:10px;min-width:0}.world-city{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12px}.world-city>span{font-size:10px;color:var(--w-muted);padding:2px 5px;border-radius:4px;background:rgba(127,145,171,.07)}.world-city .world-day{color:#b8862c;background:rgba(184,134,44,.09)}time{display:block;font:600 23px/1.5 Consolas,monospace;white-space:nowrap;margin:10px 0 7px;font-variant-numeric:tabular-nums}.world-date{display:flex;flex-direction:column;gap:4px;font-size:10px;color:var(--w-muted)}.world-note{font-size:10px;line-height:1.7;color:var(--w-muted);margin:14px 0 0}@media(max-width:700px){.world-time{padding:18px 16px}.world-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}time{font-size:20px}.world-grid article{padding:11px}}
</style>

<style scoped>
.world-city-name{display:flex;align-items:center;gap:7px;min-width:0}.world-flag{display:block;width:24px;height:18px;object-fit:cover;border-radius:3px;flex-shrink:0;box-shadow:0 0 0 1px var(--w-line)}.world-globe{display:block;flex-shrink:0;color:var(--w-muted)}
</style>
